CREATE VIRTUAL TABLE t1 USING fts4(x);WITH c(i) AS (VALUES(123),(132),(213),(231),(312),(321)) INSERT INTO t1(docid,x) SELECT i,'zero one two three' FROM c;INSERT INTO t1(x) VALUES(printf('%.*c',5000,'a'));INSERT INTO t1(x) VALUES(printf('%.*c',5000,'b'));INSERT INTO t1(x) VALUES(printf('%.*c',5000,'c'));INSERT INTO t1(x) VALUES(printf('%.*c',5000,'d'));INSERT INTO t1(x) VALUES(printf('%.*c',5000,'e'));CREATE TABLE q(n);CREATE TRIGGER rq AFTER INSERT ON q WHEN new.n<20 BEGIN INSERT INTO t1(t1) VALUES('merge=1');INSERT INTO q VALUES(new.n+1);END;INSERT INTO q VALUES(0);DROP TABLE q;CREATE TABLE q(n);CREATE TRIGGER rq AFTER INSERT ON q WHEN new.n<100 BEGIN INSERT INTO t1(t1) VALUES('merge=1,4');INSERT INTO q VALUES(new.n+1);END;INSERT INTO q VALUES(0);DROP TABLE q;